nodes.command:
node -e "
const fs = require('fs');
const zoneId = '${inputs.zone_id}';
const projectRoot = '${inputs.project_root}';

let description = '默认场景';

// 尝试从 Zone YAML 读取
const zonePath = projectRoot + '/src/data/zones/' + zoneId + '.yaml';
if (zoneId && fs.existsSync(zonePath)) {
  const yaml = require('yaml');
  const content = fs.readFileSync(zonePath, 'utf-8');
  const doc = yaml.parse(content);
  description = doc.zone_name || doc.description || zoneId;
}

console.log(JSON.stringify({ zone_id: zoneId, description: description }));
"

node -e "
const fs = require('fs');
const path = require('path');

const outputPath = '${inputs.project_root}/assets/images/backgrounds/${inputs.zone_id || inputs.task_id}.png';

if (fs.existsSync(outputPath)) {
  const stats = fs.statSync(outputPath);
  console.log('Asset validated:');
  console.log('  Path:', outputPath);
  console.log('  Size:', stats.size, 'bytes');
  console.log('  Format: PNG');
} else {
  console.log('Asset not yet created (placeholder mode)');
}
"

node -e "
const fs = require('fs');
const path = '${inputs.project_root}/src/data/asset-registry.json';
let registry = fs.existsSync(path) ? JSON.parse(fs.readFileSync(path)) : { backgrounds: {}, characters: {}, objects: {} };

registry.backgrounds = registry.backgrounds || {};
registry.backgrounds['${inputs.zone_id || inputs.task_id}'] = {
  path: 'assets/images/backgrounds/${inputs.zone_id || inputs.task_id}.png',
  width: ${inputs.width},
  height: ${inputs.height},
  format: 'PNG',
  asset_mode: 'production',
  updated_at: new Date().toISOString()
};

fs.writeFileSync(path, JSON.stringify(registry, null, 2));
console.log('Asset registry updated for:', '${inputs.zone_id || inputs.task_id}');
"
